/* ── patterns (authored in packages/governance/patterns) ── */

const PATTERNS_SRC = path.join(GOV, "patterns")
const REQUIRED_SECTIONS = ["Use when", "Don't use when", "Decision rules", "Components and variants", "Layout and density",
  "Hierarchy and composition", "Responsive behavior", "States", "Accessibility", "Anti-patterns", "Example"]
const patternErrors = []
const patterns = fs.existsSync(PATTERNS_SRC)
  ? fs.readdirSync(PATTERNS_SRC).filter((f) => f.endsWith(".md")).sort().map((file) => {
      const slug = file.replace(/\.md$/, "")
      const raw = read(path.join(PATTERNS_SRC, file))
      const fm = raw.match(/^---\n([\s\S]*?)\n---\n/)
      const summary = fm?.[1].match(/^summary:\s*(.+)$/m)?.[1].trim()
      const body = raw.replace(/^---\n[\s\S]*?\n---\n/, "")
      const title = body.match(/^# (.+)$/m)?.[1]
      const err = (m) => patternErrors.push(`patterns/${file}: ${m}`)
      if (!summary) err("front matter needs `summary:`")
      if (!title) err("needs a `# Title` heading")
      const sections = new Map()
      let cur = null
      for (const line of body.split("\n")) {
        const h = line.match(/^## (.+)$/)
        if (h) { cur = h[1].trim(); sections.set(cur, []) } else if (cur) sections.get(cur).push(line)
      }
      for (const name of REQUIRED_SECTIONS) {
        if (!sections.has(name)) err(`missing section "## ${name}"`)
        else if (!sections.get(name).some((l) => l.trim())) err(`section "## ${name}" is empty`)
      }
      // every component, variant and size named under "Components and variants" must exist in the library
      for (const line of sections.get("Components and variants") ?? []) {
        const m = line.match(/^- `(\w+)`(.*)$/)
        if (!m) { if (line.trim()) err(`unparseable line under Components and variants: ${line.trim()}`); continue }
        const comp = comps.find((c) => c.name === m[1])
        if (!comp) { err(`component ${m[1]} does not exist in packages/ui-web/src`); continue }
        for (const [, kind, vals] of m[2].matchAll(/(variant|size):\s*((?:`[\w-]+`(?:,\s*)?)+)/g)) {
          const allowed = kind === "variant" ? comp.variants : comp.sizes
          for (const v of [...vals.matchAll(/`([\w-]+)`/g)].map((x) => x[1]))
            if (!allowed?.includes(v)) err(`${m[1]} has no ${kind} \`${v}\` (${allowed?.join(", ") || "none"})`)
          // Figma is the authority: when the snapshot carries the property, the pattern may only name values Figma draws
          const drawn = comp.figma?.properties?.[kind === "variant" ? "Variant" : "Size"]
          if (drawn)
            for (const v of [...vals.matchAll(/`([\w-]+)`/g)].map((x) => x[1]))
              if (!drawn.includes(v)) err(`${m[1]} ${kind} \`${v}\` is not drawn in Figma (${drawn.join(", ")})`)
        }
      }
      // the example is a real .tsx file that tsc compiles; the generated doc embeds it
      const exFile = path.join(PATTERNS_SRC, "examples", `${slug}.example.tsx`)
      let example = null
      if (!body.includes("{{example}}")) err("Example section needs the {{example}} marker")
      if (!fs.existsSync(exFile)) err(`missing examples/${slug}.example.tsx`)
      else example = read(exFile).trimEnd()
      return { slug, file, title, summary, body, example }
    })
  : []
if (patternErrors.length) {
  console.error(`✗ pattern validation failed:\n${patternErrors.map((e) => `  ${e}`).join("\n")}`)
  process.exit(1)
}
import * as React from "react"
import { Bell } from "lucide-react"
import { EmptyState } from "@atlas/ui-web/compositions/EmptyState/EmptyState"
import { ListItem, ListItemActions, ListItemContent, ListItemDescription, ListItemMedia, ListItemTitle } from "@atlas/ui-web/compositions/ListItem/ListItem"
import { Avatar } from "@atlas/ui-web/primitives/Avatar/Avatar"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import { TabsList, TabsRoot, TabsTrigger } from "@atlas/ui-web/patterns/Tabs/Tabs"

type Notification = {
  id: string
  actor: { name: string; initials: string }
  title: string
  href: string
  when: string
  read: boolean
}

const title = { fontSize: "var(--atlas-text-h1)" }
const muted = { fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }
const visuallyHidden: React.CSSProperties = { position: "absolute", inlineSize: 1, blockSize: 1, overflow: "hidden", clipPath: "inset(50%)" }

export function NotificationsCenter({ items, loading, onChange, onMarkAllRead }: {
  items: Notification[]
  loading?: boolean
  /** Persists one item's read state. */
  onChange: (id: string, read: boolean) => void
  onMarkAllRead: () => void
}) {
  const [view, setView] = React.useState("all")
  const [announce, setAnnounce] = React.useState("")
  const unread = items.filter((n) => !n.read)
  const shown = view === "unread" ? unread : items

  const toggle = (n: Notification) => {
    onChange(n.id, !n.read)
    setAnnounce(n.read ? "Marked as unread" : "Marked as read")
  }

  return (
    <div style={{ display: "grid", gap: "var(--atlas-spacing-4)", maxInlineSize: "40rem" }}>
      <header style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: "var(--atlas-spacing-3)" }}>
        <h1 style={title}>Notifications</h1>
        <Button variant="ghost" size="sm" disabled={unread.length === 0} onClick={onMarkAllRead}>Mark all as read</Button>
      </header>

      <TabsRoot variant="line" value={view} onValueChange={setView}>
        <TabsList aria-label="Notification views">
          <TabsTrigger value="all">All</TabsTrigger>
          <TabsTrigger value="unread">{`Unread ${unread.length}`}</TabsTrigger>
        </TabsList>
      </TabsRoot>

      <div role="status" style={visuallyHidden}>{announce}</div>

      {loading ? (
        // Loading covers the list only; the header and tabs stay.
        <div role="status" aria-label="Loading notifications" style={{ display: "grid", gap: "var(--atlas-spacing-2)" }}>
          <Skeleton />
          <Skeleton />
          <Skeleton />
        </div>
      ) : shown.length === 0 ? (
        <EmptyState
          size="md"
          icon={<Bell />}
          title={view === "unread" ? "No unread notifications" : "You're all caught up"}
          action={view === "unread" ? <Button variant="outline" onClick={() => setView("all")}>View all</Button> : undefined}
        />
      ) : (
        <ul aria-label={view === "unread" ? "Unread notifications" : "All notifications"} style={{ display: "grid", gap: "var(--atlas-spacing-2)", listStyle: "none", margin: 0, padding: 0 }}>
          {shown.map((n) => (
            <ListItem key={n.id} as="li" variant={n.read ? "default" : "muted"} size="md">
              <ListItemMedia>
                <Avatar size="sm" initials={n.actor.initials} alt="" />
              </ListItemMedia>
              <ListItemContent>
                <ListItemTitle>
                  {/* The title is a real link; opening it also marks the item read. */}
                  <a href={n.href} onClick={() => { if (!n.read) onChange(n.id, true) }}>{n.title}</a>
